import {materialIcon} from './material-pixel-art.js';
import {MONSTER_CATALOG,MONSTER_MATERIALS,monsterCodexEntry,monsterMaterialPool,materialMonsterSources} from './monster-codex-schema.js';
import {icon} from './icons.js';
import {renderMonsterPixelPortrait} from './monster-pixel-portrait.js';
const esc=t=>String(t??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const elementName={earth:'地',water:'水',fire:'火',wind:'风',light:'光',dark:'暗'};
export function monsterPortrait(id,{known=true,follower=false}={}){return renderMonsterPixelPortrait(id,{known,follower});}
export function renderMonsterDetail(s,id,{follower=false}={}){const m=monsterCodexEntry(s,id);if(!m)return '<p class="monsterUnknown">暂无这份怪物记录。</p>';if(!m.encountered)return `<article class="monsterDetail">${monsterPortrait(id,{known:false})}<h2>未知怪物</h2><p>遭遇后解锁资料。</p></article>`;const mats=[...new Set(m.sources.flatMap(source=>monsterMaterialPool(id,source)))];return `<article class="monsterDetail">${monsterPortrait(id,{follower})}<div><span class="eyebrow">ENCOUNTER RECORD</span><h2>${esc(m.name)}</h2><span class="monsterRank">${m.boss?'首领':m.elite?'精英':'普通'} · 已遇见</span></div><div class="monsterTags">${m.elementTags.length?m.elementTags.map(k=>`<span data-element="${k}">${elementName[k]}</span>`).join(''):'<span>无元素标签</span>'}</div><h3>战斗技能</h3><div class="monsterSkillList">${m.skills.map(x=>`<div><strong>${esc(x.name)}</strong><small>${esc(x.description)}</small></div>`).join('')}</div><h3>精英词条</h3><p>${m.traits.length?m.traits.map(esc).join(' · '):'无额外词条'}</p><h3>可能获得的材料</h3><div class="monsterMaterials">${mats.map(key=>`<button data-monster-material="${esc(key)}" title="查看${esc(MONSTER_MATERIALS[key]?.name??key)}获取途径">${materialIcon(key,{size:32})}<span>${esc(MONSTER_MATERIALS[key]?.name??key)}</span></button>`).join('')}</div><small class="monsterFootnote">材料仅从对应怪物与地点的来源池产生；是否掉落另行判定。</small></article>`;}
export function renderMonsterCodex(s,{selectedMonster}={}){const id=Object.hasOwn(MONSTER_CATALOG,selectedMonster)?selectedMonster:Object.keys(MONSTER_CATALOG).find(k=>s.monsterLedger?.encountered?.[k])??Object.keys(MONSTER_CATALOG)[0];return `<div class="panelPage monsterCodex"><nav class="collectionTabs"><button data-codex-tab="sets">套装印记</button><button data-codex-tab="legends">传说遗物</button><button data-codex-tab="monsters" aria-pressed="true">怪物见闻</button></nav><div class="monsterCodexLayout"><div class="monsterGallery">${Object.keys(MONSTER_CATALOG).map(key=>{const m=monsterCodexEntry(s,key);return `<button class="monsterTile ${key===id?'monsterSelected':''}" data-codex-monster="${key}">${monsterPortrait(key,{known:m.encountered})}<strong>${m.encountered?esc(m.name):'未知怪物'}</strong><small>${m.encountered?'已遇见':'尚未遇见'}</small></button>`}).join('')}</div>${renderMonsterDetail(s,id)}</div><p class="monsterFootnote">怪物在实际遭遇时解锁；与需要获得物品才点亮的装备图鉴分开记录。</p></div>`;}
export function renderMaterialSources(s,key){const rows=materialMonsterSources(s,key),info=MONSTER_MATERIALS[key];return `<article class="monsterMaterialSources"><h2>${info?materialIcon(key,{size:64}):''}${esc(info?.name??key)} · 获取途径</h2>${rows.length?rows.map(r=>`<div class="monsterSource"><button data-codex-monster="${r.monsterId}">${monsterPortrait(r.monsterId,{known:r.encountered})}<span>${esc(r.monsterName)}</span></button><button data-monster-source="${r.instanceId}" ${r.available?'':'disabled'}>${esc(r.sourceName)} <small>${r.available?'查看地点':r.historical?'旧原型地点已停用 · 仅历史':'尚未开放'}</small></button></div>`).join(''):info?.source==='merchant-import-only'?'<p>游商进口 · 可从后续货单购买；不代表产地地图已开放。</p>':'<p>当前开放内容暂无可核实来源。</p>'}<p class="monsterFootnote">跳转只查看地点，不会自动出发或消耗资源。</p></article>`;}
export function bindMonsterCodex(host,{onMonster,onMaterial,onSource}){const click=e=>{const b=e.target.closest?.('[data-codex-monster],[data-monster-material],[data-monster-source]');if(!b||!host.contains(b)||b.disabled)return;const d=b.dataset;if(d.codexMonster&&Object.hasOwn(MONSTER_CATALOG,d.codexMonster))onMonster?.(d.codexMonster);else if(d.monsterMaterial&&Object.hasOwn(MONSTER_MATERIALS,d.monsterMaterial))onMaterial?.(d.monsterMaterial);else if(d.monsterSource&&Object.values(MONSTER_CATALOG).some(m=>m.sources.includes(d.monsterSource)))onSource?.(d.monsterSource);};host.addEventListener('click',click);return ()=>host.removeEventListener('click',click);}
